entries[139773] = { ["name"] = "Banner of the Mantid Empire", ["text"] = "2 sec cast\nEven with powerful magic at their disposal, the Mogu often preferred to use slaves to build their massive monuments. This ledger documents the cost, in slaves, during the construction of one such monument." }
entries[139774] = { ["name"] = "Cosmic Strike" }
